// Copies the constants and GLSL the game reads from the art session's shader
// library, art/scripts/lib/water-core.mjs, into src/world/water/core.gen.ts. The
// library's functions are ported by hand to src/world/water/core.ts;
// src/world/water/core.test.ts holds both the copy and the ports to the original,
// and fails until the two agree. Run this after the art session changes the
// library (`npm run water-core`).
//
//   node scripts/water-core.mjs           write the generated file
//   node scripts/water-core.mjs --check   exit 1 if it is out of date

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import * as core from '../art/scripts/lib/water-core.mjs'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const TARGET = path.join(root, 'src/world/water/core.gen.ts')

// What the game reads, in the order the file lists it. The library's other
// constants (MARGIN, SUPERSAMPLE, SIZE_STEP, MAX_SIDE, SD_BLUR, ENCODING) are the
// bake's, and its other functions (encode, hash12, rippleRing) are the art's.
export const EXPORTS = [
  'WATER_FORMAT', 'TEXEL', 'NOISE_SIZE',
  'BANDS', 'BAND_SOFT', 'NOISE_CELL', 'PHI', 'FLOW_CYCLE', 'PHASE_PERIODS', 'PHASE_USES',
  'TIERS', 'PALETTES', 'BODY_PALETTE', 'RIPPLE', 'RIPPLE_BODIES', 'WATER_UNIFORMS',
  'WATER_VERT_PARS', 'WATER_VERT', 'WATER_FRAG_PARS', 'WATER_COLOR', 'WATER_LIGHT', 'WATER_ANCHORS',
]

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/
const WIDTH = 110

/** A multi-line string as a template literal, escaped so it evaluates to exactly the string. */
function template(s) {
  return '`' + s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${') + '`'
}

/** A value on one line. */
function inline(v) {
  if (Array.isArray(v)) return `[${v.map(inline).join(', ')}]`
  if (v && typeof v === 'object') {
    const entries = Object.entries(v)
    return entries.length ? `{ ${entries.map(([k, x]) => `${key(k)}: ${inline(x)}`).join(', ')} }` : '{}'
  }
  return JSON.stringify(v)
}

const key = (k) => (IDENTIFIER.test(k) ? k : JSON.stringify(k))

/** A value as TypeScript source: on one line if it fits, else one entry a line. */
function literal(v, pad = '') {
  if (typeof v === 'string' && v.includes('\n')) return template(v)
  const one = inline(v)
  if (typeof v !== 'object' || v === null || pad.length + one.length <= WIDTH) return one
  const inner = pad + '  '
  if (Array.isArray(v)) return `[\n${v.map((x) => `${inner}${literal(x, inner)},\n`).join('')}${pad}]`
  return `{\n${Object.entries(v).map(([k, x]) => `${inner}${key(k)}: ${literal(x, inner)},\n`).join('')}${pad}}`
}

function render() {
  const lines = [
    '// Generated by scripts/water-core.mjs from art/scripts/lib/water-core.mjs.',
    "// Do not edit it by hand: ask the art session to change the library, then run `npm run water-core`.",
    '// core.test.ts fails while this and the original disagree.',
    '',
  ]
  for (const name of EXPORTS) {
    const value = core[name]
    if (value === undefined) throw new Error(`water-core.mjs no longer exports ${name}`)
    const asConst = typeof value === 'object' ? ' as const' : ''
    lines.push(`export const ${name} = ${literal(value)}${asConst}`, '')
  }
  return lines.join('\n')
}

export function generate() {
  return render()
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const text = generate()
  if (process.argv.includes('--check')) {
    const now = fs.existsSync(TARGET) ? fs.readFileSync(TARGET, 'utf8') : ''
    if (now !== text) {
      console.error('src/world/water/core.gen.ts is out of date: run `npm run water-core`.')
      process.exit(1)
    }
    console.log('src/world/water/core.gen.ts matches water-core.')
  } else {
    fs.mkdirSync(path.dirname(TARGET), { recursive: true })
    fs.writeFileSync(TARGET, text)
    console.log(`wrote ${path.relative(root, TARGET)} (${(text.length / 1024).toFixed(1)} KB)`)
  }
}
